    private static BusinessUnitState Unit(string project, string path, string name, BusinessUnitKind kind)
    {
        Address address = Address.FromPublicKey(System.Text.Encoding.UTF8.GetBytes($"{project}:{path}"));
        return new BusinessUnitState(project, LedgerSimulatorIdentifiers.BusinessUnitId(project, path), name, kind, null, address, path, kind is BusinessUnitKind.CostCenter ? path : null, kind is BusinessUnitKind.RevenueCenter ? path : null, null, "EUR", false, false, BusinessUnitStatus.Active, [address], Empty(), Empty());
    }

    private static ScenarioFinancialScheduleState Schedule(
        string project,
        string scheduleId,
        string? parentScheduleId,
        BusinessUnitState businessUnit,
        string displayName,
        ScenarioFinancialScheduleKind kind,
        FinancialStatementSection section,
        EconomicEventKind eventKind,
        EconomicImpactKind impactKind,
        string categoryCode,
        bool requiresApproval,
        bool postsToSimulation,
        ScenarioApprovalState? approval,
        IReadOnlyList<ScenarioFinancialScheduleAmountState> amounts,
        IReadOnlyDictionary<string, string> metadata)
        => new(project, scheduleId, parentScheduleId, businessUnit.BusinessUnitId, displayName, kind, section, eventKind, impactKind, categoryCode, requiresApproval, postsToSimulation, approval, amounts, metadata);

    private static ScenarioApprovalState Approval(
        ScenarioApprovalStatus status,
        ScenarioApprovalScope scope,
        decimal selfApprovalLimit,
        BusinessUnitState requestingBusinessUnit,
        BusinessUnitState approvingBusinessUnit,
        DateOnly requestedDate,
        DateOnly approvedDate,
        IReadOnlyDictionary<string, string> metadata)
        => new(status, scope, Amount.FromDecimal(selfApprovalLimit), requestingBusinessUnit.BusinessUnitId, approvingBusinessUnit.BusinessUnitId, requestedDate, approvedDate, metadata);

    private static IReadOnlyList<ScenarioFinancialScheduleAmountState> Amounts(params (DateOnly Date, decimal Amount, string LegacyCellReference, IReadOnlyDictionary<string, string> Metadata)[] items)
        => items.Select(x => new ScenarioFinancialScheduleAmountState(x.Date, Amount.FromDecimal(x.Amount), LedgerSimulatorPeriods.MonthKey(x.Date), Meta(x.Metadata.Select(item => (item.Key, item.Value)).ToArray()))).ToArray();

    private static IReadOnlyDictionary<string, string> Empty() => new Dictionary<string, string>();

    private static IReadOnlyDictionary<string, string> Meta(params (string Key, string Value)[] items)
    {
        var metadata = new Dictionary<string, string>(StringComparer.Ordinal)
        {
            ["assemblySource"] = "vef-financial-plan-assembly"
        };

        foreach ((string key, string value) in items)
        {
            AddAssemblyMetadata(metadata, key, value);
        }

        return metadata;
    }

    private static void AddAssemblyMetadata(Dictionary<string, string> metadata, string key, string value)
    {
        string? assemblyKey = key switch
        {
            "sourceWorkbook" or "sourceSheet" or "sourceRow" or "sourceColumn" => null,
            "sourceLabel" => "planLabel",
            "workbookSection" => "planSection",
            "workbookVisibleYears" => "planningYears",
            "workbookTruth" => "assemblyBaseline",
            "excelCashArtifact" => "cashReconciliationNote",
            "excelReconciliation" => "reconciliationNote",
            "excelRowMeaning" => "planLineMeaning",
            _ when key.Contains("Row", StringComparison.OrdinalIgnoreCase) => key
                .Replace("Row5", string.Empty, StringComparison.Ordinal)
                .Replace("Row36", string.Empty, StringComparison.Ordinal)
                .Replace("Row41", string.Empty, StringComparison.Ordinal)
                .Replace("Row43", string.Empty, StringComparison.Ordinal)
                .Replace("Row44", string.Empty, StringComparison.Ordinal),
            _ => key
        };

        if (string.IsNullOrWhiteSpace(assemblyKey))
        {
            return;
        }

        metadata[assemblyKey] = value;
    }
